    ["Angelica "] = "Анжелика",
    ["Is the invitation letter the name of the Sequence potion?"] = "Приглашение — это название серийного зелья?",
    ["Not really, Captain Frye sent me to investigate and verify some information on the disappearance cases."] = "Это неправда. Капитан Фрай послал меня расследовать и проверить информацию о нескольких исчезновениях.",
