    ["Floor tile 6-2"] = "Напольная плитка 6-2",
    ["<P_Heart> (It's almost time for the appointment... Let's go to the Lakeside to meet Andy.)</>"] = "<P_Heart> (Время уже почти назначено... Давайте встретим Энди у озера.) </>",
    ["But I didn't..."] = "Но я не...",
    ["<P_Heart>(He took a detour... as if he were avoiding an invisible stone?)</>"] = "<P_Heart> (Он ходил... как будто избегал несуществующего камня?) </>",
